-- Schema (TDD §10). Applied by the Supabase CLI in prod and by `python -m app.db.migrate` locally.
-- Conventions (§10.1): per-user tables carry user_id uuid not null, run_id text not null default 'live',
-- created_at timestamptz default now(). Shared tables have no user_id. Agent artifact ids are text
-- (ULIDs generated by the app); user ids are UUIDs.

-- ---- roles --------------------------------------------------------------------------------------
-- app_rw: what the backend connects as. NOT bypassrls (the default) and not the table owner, so
-- every policy below applies to it. app_admin: read-only admin views (profiles, jobs, llm_calls).
-- Passwords / LOGIN are set out of band (docs/deploy.md), never in a migration.
do $$
begin
  if not exists (select 1 from pg_roles where rolname = 'app_rw') then
    create role app_rw nologin;
  end if;
  if not exists (select 1 from pg_roles where rolname = 'app_admin') then
    create role app_admin nologin;
  end if;
end
$$;

-- ---- shared (newsroom) tables ----------------------------------------------------------------------

create table if not exists headline_observations (
  id            text primary key default gen_random_uuid()::text,
  run_id        text not null default 'live',
  source_id     text not null,
  beat          text not null,
  observed_at   timestamptz not null,
  url           text not null,
  title         text not null,
  rank          int,
  snippet       text,
  engagement    jsonb,
  published_at  timestamptz,
  external_id   text,
  created_at    timestamptz not null default now()
);
create index if not exists headline_observations_src_idx
  on headline_observations (run_id, source_id, observed_at desc);

create table if not exists documents (
  url_hash       text primary key,
  url            text not null,
  canonical_url  text,
  title          text,
  source         text,
  published_at   timestamptz,
  available_at   timestamptz,
  fetched_at     timestamptz not null default now(),
  text           text not null default '',
  extractor_ver  text not null default 'v0'
);

create table if not exists passages (
  id             text primary key,
  url_hash       text not null references documents (url_hash) on delete cascade,
  text           text not null,
  char_start     int not null,
  char_end       int not null,
  extractor_ver  text not null default 'v0',
  created_at     timestamptz not null default now()
);
create index if not exists passages_doc_idx on passages (url_hash);

create table if not exists stories (
  id          text primary key,
  run_id      text not null default 'live',
  first_seen  timestamptz not null,
  beat        text not null,
  title       text not null,
  subtopics   text[] not null default '{}',
  entities    text[] not null default '{}',
  embedding   bytea,
  update_of   text,
  created_at  timestamptz not null default now()
);

create table if not exists story_items (
  id              bigint generated always as identity primary key,
  story_id        text not null references stories (id) on delete cascade,
  url_hash        text,
  observation_id  text,
  created_at      timestamptz not null default now(),
  check (url_hash is not null or observation_id is not null)
);
create index if not exists story_items_story_idx on story_items (story_id);

create table if not exists newsroom_runs (
  id          text primary key,
  run_id      text not null default 'live',
  beat        text not null,
  at          timestamptz not null,
  status      text not null default 'running',
  cost        numeric(12, 6),
  trace_uri   text,
  created_at  timestamptz not null default now()
);

create table if not exists digests (
  id          text primary key,
  run_id      text not null default 'live',
  beat        text not null,
  at          timestamptz not null,
  version     text not null,
  created_at  timestamptz not null default now()
);
create index if not exists digests_beat_at_idx on digests (run_id, beat, at desc);

create table if not exists digest_entries (
  digest_id         text not null references digests (id) on delete cascade,
  story_id          text not null,
  headline          text not null,
  summary           text not null default '',
  subtopics         text[] not null default '{}',
  entities          text[] not null default '{}',
  importance        int not null,
  importance_rules  real,
  evidence          jsonb not null default '[]',
  is_update_of      text,
  features          jsonb,
  urls              jsonb not null default '[]',
  primary key (digest_id, story_id)
);

-- ---- per-user tables (RLS) --------------------------------------------------------------------------

create table if not exists profiles (
  user_id           uuid primary key,
  run_id            text not null default 'live',
  email             text,
  display_name      text,
  timezone          text not null default 'America/Los_Angeles',
  brief_time        time not null default '07:00',
  status            text not null default 'onboarding'
                    check (status in ('onboarding', 'active', 'paused')),
  type              text not null default 'real' check (type in ('real', 'synthetic')),
  role              text not null default 'user' check (role in ('user', 'admin')),
  research_consent  boolean not null default false,
  settings          jsonb not null default '{}',
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now()
);

create table if not exists interests (
  id                  text not null default gen_random_uuid()::text,  -- unique per user + run
  user_id             uuid not null references profiles (user_id) on delete cascade,
  run_id              text not null default 'live',
  label               text not null,
  subtopic            text not null,
  entity              text,
  kind                text not null default 'topic' check (kind in ('topic', 'entity', 'keep_posted')),
  weight              double precision not null default 0,
  confidence          double precision not null default 0,
  explicit_pin        boolean not null default false,
  shown_n             int not null default 0,
  engaged_n           int not null default 0,
  last_reinforced_at  timestamptz,
  source              text not null check (source in ('onboarding', 'explicit', 'implicit', 'exploration')),
  evidence            jsonb not null default '[]',
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now(),
  primary key (user_id, run_id, id)
);
create index if not exists interests_user_idx on interests (user_id, run_id);

create table if not exists delivery_prefs (
  user_id     uuid not null references profiles (user_id) on delete cascade,
  run_id      text not null default 'live',
  key         text not null check (key in ('length_s', 'depth', 'technicality', 'style', 'preferred_sources')),
  value       jsonb not null,
  confidence  double precision not null default 0.5,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now(),
  primary key (user_id, run_id, key)
);

create table if not exists memory_snapshots (
  id           text primary key default gen_random_uuid()::text,
  user_id      uuid not null references profiles (user_id) on delete cascade,
  run_id       text not null default 'live',
  as_of_date   date not null,
  payload      jsonb not null,
  created_at   timestamptz not null default now(),
  unique (user_id, run_id, as_of_date)
);

create table if not exists briefs (
  id              text primary key,
  user_id         uuid not null references profiles (user_id) on delete cascade,
  run_id          text not null default 'live',
  local_date      date not null,
  arm             text not null default 'full',
  status          text not null default 'preparing'
                  check (status in ('preparing', 'rendering', 'ready', 'failed', 'fallback')),
  script          jsonb,
  selection       jsonb,
  audio_manifest  jsonb,
  cost            numeric(12, 6),
  trace_uri       text,
  created_at      timestamptz not null default now(),
  ready_at        timestamptz,
  unique (user_id, run_id, local_date, arm)
);

create table if not exists candidates (
  id          text primary key default gen_random_uuid()::text,
  brief_id    text not null references briefs (id) on delete cascade,
  user_id     uuid not null references profiles (user_id) on delete cascade,
  run_id      text not null default 'live',
  story_ref   text not null,
  origin      text not null check (origin in ('digest', 'personal', 'adjacent', 'carryover', 'update')),
  headline    text,
  scores      jsonb,
  created_at  timestamptz not null default now()
);
create index if not exists candidates_brief_idx on candidates (brief_id);

create table if not exists source_packs (
  brief_id    text not null references briefs (id) on delete cascade,
  story_id    text not null,
  user_id     uuid not null references profiles (user_id) on delete cascade,
  run_id      text not null default 'live',
  pack        jsonb not null,
  created_at  timestamptz not null default now(),
  primary key (brief_id, story_id)
);

create table if not exists sessions (
  id                text primary key,
  user_id           uuid not null references profiles (user_id) on delete cascade,
  run_id            text not null default 'live',
  brief_id          text references briefs (id) on delete set null,
  started_at        timestamptz not null default now(),
  ended_at          timestamptz,
  end_reason        text check (end_reason in ('natural', 'cut_short', 'idle', 'error')),
  time_available_s  int,
  client            jsonb not null default '{}',
  state             text not null default 'READY',
  position          jsonb,
  created_at        timestamptz not null default now()
);
create index if not exists sessions_user_idx on sessions (user_id, started_at desc);

create table if not exists turns (
  id            text primary key,
  session_id    text not null references sessions (id) on delete cascade,
  user_id       uuid not null references profiles (user_id) on delete cascade,
  run_id        text not null default 'live',
  seq           int not null default 0,
  role          text not null check (role in ('user', 'agent', 'system')),
  text          text not null default '',
  action        text,
  story_ref     text,
  citations     jsonb not null default '[]',
  playback_pos  jsonb,
  timings       jsonb,
  created_at    timestamptz not null default now()
);
create index if not exists turns_session_idx on turns (session_id, seq);

create table if not exists memory_signals (
  id             text primary key default gen_random_uuid()::text,
  user_id        uuid not null references profiles (user_id) on delete cascade,
  run_id         text not null default 'live',
  session_id     text,
  type           text not null,
  story_ref      text,
  interest_hint  text,
  strength       double precision not null default 1.0,
  explicit       boolean not null default false,
  turn_id        text,
  payload        jsonb not null default '{}',
  session_ctx    jsonb,
  created_at     timestamptz not null default now()
);
create index if not exists memory_signals_session_idx on memory_signals (session_id);

create table if not exists open_questions (
  id           text primary key,
  user_id      uuid not null references profiles (user_id) on delete cascade,
  run_id       text not null default 'live',
  session_id   text,
  story_ref    text,
  question     text not null,
  context      jsonb not null default '{}',
  status       text not null default 'open'
               check (status in ('open', 'researching', 'answered', 'unanswerable', 'delivered', 'dismissed')),
  answer       jsonb,
  citations    jsonb not null default '[]',
  created_at   timestamptz not null default now(),
  answered_at  timestamptz,
  expires_at   timestamptz
);

create table if not exists saved_items (
  id          text primary key default gen_random_uuid()::text,
  user_id     uuid not null references profiles (user_id) on delete cascade,
  run_id      text not null default 'live',
  story_id    text not null,
  session_id  text,
  status      text not null default 'saved',
  created_at  timestamptz not null default now(),
  unique (user_id, run_id, story_id)
);

create table if not exists ratings (
  id               text primary key,
  user_id          uuid not null references profiles (user_id) on delete cascade,
  run_id           text not null default 'live',
  session_id       text,
  usefulness       int check (usefulness between 1 and 5),
  per_story        jsonb not null default '{}',
  learned_new      boolean,
  length_fit       text,
  followup_useful  int,
  created_at       timestamptz not null default now()
);

create table if not exists experiment_assignments (
  user_id     uuid not null references profiles (user_id) on delete cascade,
  run_id      text not null default 'live',
  local_date  date not null,
  arm         text not null,
  created_at  timestamptz not null default now(),
  primary key (user_id, run_id, local_date)
);

create table if not exists topic_requests (
  id          text primary key default gen_random_uuid()::text,
  user_id     uuid not null references profiles (user_id) on delete cascade,
  run_id      text not null default 'live',
  text        text not null,
  created_at  timestamptz not null default now()
);

-- Cost ledger. user_id is informational (no FK): rows outlive account deletion with user_id nulled.
create table if not exists llm_calls (
  id             bigint generated always as identity primary key,
  run_id         text not null default 'live',
  user_id        uuid,
  job_id         text,
  role           text not null,
  provider       text not null,
  model          text not null,
  tokens_in      int not null default 0,
  tokens_out     int not null default 0,
  tokens_cached  int not null default 0,
  cost_usd       numeric(12, 6),
  latency_ms     int,
  cached         boolean not null default false,
  created_at     timestamptz not null default now()
);
create index if not exists llm_calls_created_idx on llm_calls (created_at);

-- ---- system tables ------------------------------------------------------------------------------------

create table if not exists jobs (
  id            bigint generated always as identity primary key,
  type          text not null,
  dedupe_key    text unique,
  user_id       uuid,
  run_id        text not null default 'live',
  priority      int not null default 5,
  run_at        timestamptz not null default now(),
  status        text not null default 'queued'
                check (status in ('queued', 'running', 'done', 'failed', 'paused', 'cancelled')),
  attempts      int not null default 0,
  max_attempts  int not null default 3,
  last_error    text,
  payload       jsonb not null default '{}',
  locked_by     text,
  locked_at     timestamptz,
  created_at    timestamptz not null default now(),
  finished_at   timestamptz
);
create index if not exists jobs_claim_idx on jobs (priority, run_at) where status = 'queued';

create table if not exists invites (
  email        text primary key,
  invited_by   uuid,
  role         text not null default 'user' check (role in ('user', 'admin')),
  created_at   timestamptz not null default now(),
  accepted_at  timestamptz
);

create table if not exists admin_audit (
  id           bigint generated always as identity primary key,
  admin_id     uuid,
  action       text not null,
  target_user  uuid,
  detail       jsonb not null default '{}',
  created_at   timestamptz not null default now()
);

create table if not exists worker_heartbeats (
  worker_id  text primary key,
  seen_at    timestamptz not null default now(),
  info       jsonb not null default '{}'
);

create table if not exists admin_alerts (
  id          bigint generated always as identity primary key,
  key         text unique not null,
  kind        text not null,
  message     text not null,
  created_at  timestamptz not null default now()
);
